            h = h xor c.code.toLong()
            h *= 1099511628211L
        }
        return h
    }

    private fun prepare() {
        if (keys.isNotEmpty()) return
        /* 哈希和档位编进一个 Long：低 8 位是档位，其余是哈希。 */
        var n = 0
        var p = 0
        while (p < hard.length) {
            var q = hard.indexOf('\n', p)
            if (q < 0) q = hard.length
            n++
            p = q + 1
        }
        p = 0
        while (p < soft.length) {
            var q = soft.indexOf('\n', p)
            if (q < 0) q = soft.length
            n++
            p = q + 1
        }
        val arr = LongArray(n + 2)
        var i = 0
        p = 0
        while (p < hard.length) {
            var q = hard.indexOf('\n', p)
            if (q < 0) q = hard.length
            if (q > p) arr[i++] = hash(hard.substring(p, q)) shl 8
            p = q + 1
        }
        p = 0
        while (p < soft.length) {
            var q = soft.indexOf('\n', p)
            if (q < 0) q = soft.length
            if (q > p) arr[i++] = (hash(soft.substring(p, q)) shl 8) or 1L
            p = q + 1
        }
        keys = arr.copyOf(i)
        keys.sort()
    }

    /** 0 = 不在表里；1 = 一眼不是人；2 = 普通名词，要看它当主语的比例。 */
    fun kind(w: String): Int {
        if (w.length < 2 || w.length > 4) return 0
        prepare()
        /* 低 8 位存档位，比较时先抹掉，不然二档那些词永远匹配不上。 */
        val k = hash(w) shl 8
        var lo = 0
        var hi = keys.size - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            val v = keys[mid] and LOW
            if (v < k) lo = mid + 1
            else if (v > k) hi = mid - 1
            else return (keys[mid] and 0xFF).toInt() + 1
        }
        return 0
    }
}
